//! Compiling one `.boxy` unit to a wasm unit image (`WasmUnitImage`).
//!
//! The unit's procedures are generated by `WasmCodeGen` exactly as a
//! whole-program wasm object generates them, with one difference: nothing
//! is merged into the unit's module. The builtins, the Boxy runtime, the
//! runtime set, the platform's hosted functions and the procedures other
//! units export (`LIR.LirProcSpec.linked`) are function imports with the
//! signatures the generated calls use (`WasmCodeGen.registerUnitImports`),
//! and the unit's own exported procedures and entry wrappers keep global
//! names. The image is then read straight off the generated module: its
//! bodies, its data segments, and its relocations, which become the image's
//! sites. The constants the program named for itself are defined weak under
//! content names and referenced by name (`contentNamedStaticData`), so a
//! link keeps one copy of a constant the program's units share. Data and
//! table references keep the position-independent form of
//! every wasm object Roc emits (`__memory_base` and `__table_base` plus an
//! offset), so one image serves every output kind.

const std = @import("std");
const base = @import("base");
const layout = @import("layout");
const lir = @import("lir");
const roc_target = @import("roc_target");

const WasmModule = @import("WasmModule.zig");
const WasmCodeGen = @import("WasmCodeGen.zig");
const WasmLinking = @import("WasmLinking.zig");
const WasmUnitImage = @import("WasmUnitImage.zig");
const StackRoom = @import("StackRoom.zig");
const StaticDataExport = @import("../dev/StaticDataExport.zig").StaticDataExport;
const CodeExcerpt = @import("../dev/CodeExcerpt.zig");
const collectRequiredRcHelpers = @import("../dev/StaticDataExport.zig").collectRequiredRcHelpers;
const tasks = base.post_check_task_executor;

const Allocator = std.mem.Allocator;

/// A host-callable entry wrapper the unit exports under `symbol_name`.
pub const Entry = struct {
    symbol_name: []const u8,
    proc: lir.LIR.LirProcSpecId,
    arg_layouts: []const layout.Idx,
    ret_layout: layout.Idx,
};

/// What a unit's compilation needs beyond its lowered program.
pub const Options = struct {
    cpu_level: roc_target.CpuLevel,
    /// Whether the platform reserves low memory, so the unit's code checks
    /// its stack bounds.
    stack_checks: bool,
    executor: ?tasks.Executor = null,
};

/// Why a unit could not be compiled to an image.
pub const Error = WasmCodeGen.HostedSymbolError || WasmModule.MergeError || WasmModule.StaticDataError || WasmUnitImage.EncodeError || StackRoom.Error;

/// Compile the unit whose LIR is `store` and encode its image. The caller
/// owns the result.
pub fn compileUnitImage(
    gpa: Allocator,
    store: *const lir.LirStore,
    layouts: *const layout.Store,
    entrypoints: []const Entry,
    static_data: []const StaticDataExport,
    options: Options,
) Error![]align(WasmUnitImage.alignment.toByteUnits()) u8 {
    // The content names of the unit's static data live as long as the
    // module naming them.
    var naming_arena = std.heap.ArenaAllocator.init(gpa);
    defer naming_arena.deinit();
    var module = WasmModule.init(gpa);
    var module_owned_here = true;
    errdefer if (module_owned_here) module.deinit();
    module.addMemoryImport();
    const table_symbol = try module.addTableImportWithSymbol();
    const stack_pointer_symbol = try module.addStackPointerImportWithSymbol();

    var codegen = WasmCodeGen.initWithModule(gpa, store, layouts, &module, options.cpu_level);
    module_owned_here = false;
    defer codegen.deinit();
    codegen.executor = options.executor;
    codegen.configureStackPointerReloc(stack_pointer_symbol);
    codegen.configureTableReloc(table_symbol);
    codegen.configureRelocatableObject();

    const procs = store.getProcSpecs();
    try codegen.registerUnitImports(procs, store.runtime_contract == .boxy);
    // The codegen reads the callees until its bodies are flushed.
    var callees: std.ArrayList([]const u8) = .empty;
    defer callees.deinit(gpa);
    if (options.stack_checks) {
        for (static_data) |data_export| for (data_export.relocations) |relocation| {
            if (relocation.kind == .function_pointer) try callees.append(gpa, relocation.target_symbol_name);
        };
        try codegen.configureStackChecks(callees.items);
    }

    const static_rc_helpers = try collectRequiredRcHelpers(gpa, static_data);
    defer gpa.free(static_rc_helpers);
    codegen.static_data_rc_helpers = static_rc_helpers;
    try codegen.registerIndirectCallTypes();
    try codegen.compileAllProcSpecs(procs);
    try codegen.compileStaticDataRcHelpers(static_rc_helpers);
    for (entrypoints) |entry| {
        _ = try codegen.generateEntrypointWrapper(entry.symbol_name, entry.proc, entry.arg_layouts, entry.ret_layout);
    }
    try codegen.flushPendingBodies();

    if (static_data.len != 0) {
        // A function pointer in static data names a function of this unit
        // or one another unit exports, which the unit imports.
        for (static_data) |data_export| for (data_export.relocations) |relocation| {
            if (relocation.kind != .function_pointer) continue;
            const symbol = codegen.module.linking.findSymbolByName(relocation.target_symbol_name, codegen.module.imports.items, codegen.module.global_imports.items, codegen.module.table_imports.items) orelse
                base.invariant("wasm unit invariant violated: static data names function {s}, which the unit neither defines nor imports", .{relocation.target_symbol_name});
            if (codegen.module.linking.symbol_table.items[symbol].kind != .function) base.invariant("wasm unit invariant violated: static data names {s} as a function, but it is not one", .{relocation.target_symbol_name});
        };
        const named = try contentNamedStaticData(gpa, naming_arena.allocator(), static_data);
        var static_module = try WasmModule.staticDataModule(gpa, named);
        defer static_module.deinit();
        var merge_result = try codegen.module.mergeModuleForObject(&static_module);
        merge_result.deinit();
    }

    const stack_low: ?u32 = if (codegen.stack_checks) |symbols| symbols.stack_low.raw() else null;
    return imageOfModule(gpa, &codegen.module, options.stack_checks, stack_low);
}

/// The unit's static data with every constant the program named for itself
/// under its content name (`CodeExcerpt.ContentNames`): the nodes of its
/// descriptors, dictionaries, names and carried values, named by the digest
/// of their bytes and references and defined weak, so the units of a program
/// that carry one constant define one symbol and a link keeps one of them. A
/// constant the unit's code names (one holding a static-data value), a
/// mutable constant, and a constant the host sees keep the program's names.
/// Two constants of the unit with one content name are one constant: the
/// second is left out and every reference to it names the first.
fn contentNamedStaticData(gpa: Allocator, arena: Allocator, static_data: []const StaticDataExport) Allocator.Error![]const StaticDataExport {
    var names = try CodeExcerpt.ContentNames.initObjectData(gpa, static_data);
    defer names.deinit();
    var renamed: std.ArrayList(StaticDataExport) = .empty;
    var defined: std.StringHashMapUnmanaged(void) = .empty;
    for (static_data) |data_export| {
        const content_name = names.of(data_export.symbol_name);
        const shared = data_export.value_id == null and !data_export.is_mutable and !data_export.is_exported and content_name.ptr != data_export.symbol_name.ptr;
        if (shared and (try defined.getOrPut(arena, content_name)).found_existing) continue;
        const relocations = try arena.alloc(@import("../dev/StaticDataExport.zig").StaticDataRelocation, data_export.relocations.len);
        for (data_export.relocations, relocations) |relocation, *out| {
            out.* = relocation;
            if (relocation.kind == .address) out.target_symbol_name = try arena.dupe(u8, names.of(relocation.target_symbol_name));
        }
        var out = data_export;
        out.relocations = relocations;
        if (shared) {
            out.symbol_name = try arena.dupe(u8, content_name);
            out.is_global = true;
            out.content_named = true;
        }
        try renamed.append(arena, out);
    }
    return renamed.items;
}

/// The image of a unit's generated module: every defined function and data
/// segment, every relocation as a site, and exactly the imports the sites
/// name. `stack_low` is the symbol the unit's stack checks compare against.
pub fn imageOfModule(gpa: Allocator, module: *const WasmModule, stack_checks: bool, stack_low: ?u32) Error![]align(WasmUnitImage.alignment.toByteUnits()) u8 {
    var arena_state = std.heap.ArenaAllocator.init(gpa);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    if (module.extra_globals.items.len != 0) base.invariant("wasm unit invariant violated: a unit defines {d} globals", .{module.extra_globals.items.len});
    const import_count = module.importCount();
    const symbols = module.linking.symbol_table.items;

    var types: Types = .{ .arena = arena, .module = module };
    var imports: Imports = .{ .arena = arena, .module = module };
    try imports.collect(module.reloc_code.entries.items, module.reloc_data.entries.items);

    // Functions, their bodies and their sites.
    const code_relocs = try arena.dupe(WasmLinking.RelocationEntry, module.reloc_code.entries.items);
    std.mem.sort(WasmLinking.RelocationEntry, code_relocs, {}, struct {
        fn lessThan(_: void, a: WasmLinking.RelocationEntry, b: WasmLinking.RelocationEntry) bool {
            return a.getOffset() < b.getOffset();
        }
    }.lessThan);
    const function_count = module.function_offsets.items.len;
    const functions = try arena.alloc(WasmUnitImage.InputFunction, function_count);
    const requested = try arena.alloc(bool, function_count);
    @memset(requested, false);
    var next_reloc: usize = 0;
    for (functions, 0..) |*function, local| {
        var cursor: usize = module.function_offsets.items[local];
        const body_size = WasmModule.readU32(module.code_bytes.items, &cursor) catch unreachable; // the codegen wrote this size prefix
        const body_start: u32 = @intCast(cursor);
        const body_end = body_start + body_size;
        const body = try arena.dupe(u8, module.code_bytes.items[body_start..body_end]);
        var sites: std.ArrayList(WasmUnitImage.InputSite) = .empty;
        while (next_reloc < code_relocs.len and code_relocs[next_reloc].getOffset() < body_end) : (next_reloc += 1) {
            const entry = code_relocs[next_reloc];
            std.debug.assert(entry.getOffset() >= body_start);
            const site = try siteOf(entry, entry.getOffset() - body_start, false, symbols, import_count, &types, &imports, stack_low);
            zeroField(body, site);
            markTableSite(site, requested, imports.list.items);
            try sites.append(arena, site);
        }
        function.* = .{
            .body = body,
            .type = try types.of(module.func_type_indices.items[local]),
            .export_name = null,
            .sites = sites.items,
        };
    }
    std.debug.assert(next_reloc == code_relocs.len);

    // Segments and their sites.
    const data_relocs = try arena.dupe(WasmLinking.RelocationEntry, module.reloc_data.entries.items);
    std.mem.sort(WasmLinking.RelocationEntry, data_relocs, {}, struct {
        fn segmentOf(entry: WasmLinking.RelocationEntry) u32 {
            return switch (entry) {
                .index => |index| index.data_segment_index,
                .offset => |offset| offset.data_segment_index,
            };
        }
        fn lessThan(_: void, a: WasmLinking.RelocationEntry, b: WasmLinking.RelocationEntry) bool {
            if (segmentOf(a) != segmentOf(b)) return segmentOf(a) < segmentOf(b);
            return a.getOffset() < b.getOffset();
        }
    }.lessThan);
    const segments = try arena.alloc(WasmUnitImage.InputSegment, module.data_segments.items.len);
    next_reloc = 0;
    for (segments, module.data_segments.items, 0..) |*segment, source, index| {
        const bytes = try arena.dupe(u8, source.data);
        var sites: std.ArrayList(WasmUnitImage.InputSite) = .empty;
        while (next_reloc < data_relocs.len) : (next_reloc += 1) {
            const entry = data_relocs[next_reloc];
            const segment_index = switch (entry) {
                .index => |reloc| reloc.data_segment_index,
                .offset => |reloc| reloc.data_segment_index,
            };
            if (segment_index != index) break;
            const site = try siteOf(entry, entry.getOffset(), true, symbols, import_count, &types, &imports, stack_low);
            zeroField(bytes, site);
            markTableSite(site, requested, imports.list.items);
            try sites.append(arena, site);
        }
        if (source.zero_fill and sites.items.len != 0) base.invariant("wasm unit invariant violated: a zero-fill segment holds relocations", .{});
        segment.* = .{
            .bytes = if (source.zero_fill) null else bytes,
            .size = @intCast(source.data.len),
            .alignment_log2 = source.alignment,
            .sites = sites.items,
        };
    }
    if (next_reloc != data_relocs.len) base.invariant("wasm unit invariant violated: a data relocation names no segment of the unit", .{});

    // Exported functions and data symbols: definitions that are neither
    // local nor hidden.
    var data_exports: std.ArrayList(WasmUnitImage.InputDataExport) = .empty;
    for (symbols) |symbol| {
        if (symbol.isUndefined()) continue;
        if (symbol.flags & (WasmLinking.SymFlag.BINDING_LOCAL | WasmLinking.SymFlag.VISIBILITY_HIDDEN) != 0) continue;
        switch (symbol.kind) {
            .function => {
                const local = symbol.index - import_count;
                if (functions[local].export_name != null) base.invariant("wasm unit invariant violated: function {d} is exported under two names", .{local});
                functions[local].export_name = symbol.name orelse base.invariant("wasm unit invariant violated: an exported function has no name", .{});
            },
            .data => try data_exports.append(arena, .{
                .name = symbol.name orelse base.invariant("wasm unit invariant violated: an exported data symbol has no name", .{}),
                .segment = symbol.index,
                .offset = symbol.data_offset,
                .size = symbol.data_size,
                .weak = sharedDataDefinition(symbol),
            }),
            .global, .table, .section, .event => base.invariant("wasm unit invariant violated: a unit defines a {s} symbol", .{@tagName(symbol.kind)}),
        }
    }

    if (stack_checks) {
        const frames = try StackRoom.unitFrames(arena, module);
        for (functions, frames) |*function, frame| {
            const calls = try arena.alloc(WasmUnitImage.InputCall, frame.calls.len);
            for (calls, frame.calls) |*call, source| call.* = switch (source.callee) {
                .defined => |local| .{ .target_kind = .function, .target = local, .depth = try depth32(source.depth) },
                .import_symbol => |symbol| .{ .target_kind = .import, .target = imports.indexOfSymbol(symbol), .depth = try depth32(source.depth) },
                .indirect => |type_index| .{ .target_kind = .type, .target = try types.of(type_index), .depth = try depth32(source.depth) },
            };
            std.mem.sort(WasmUnitImage.InputCall, calls, {}, struct {
                fn lessThan(_: void, a: WasmUnitImage.InputCall, b: WasmUnitImage.InputCall) bool {
                    if (a.target_kind != b.target_kind) return @backingInt(a.target_kind) < @backingInt(b.target_kind);
                    if (a.target != b.target) return a.target < b.target;
                    return a.depth < b.depth;
                }
            }.lessThan);
            function.frame_depth = try depth32(frame.own_depth);
            function.calls = calls;
            function.checked = frame.checked;
        }
    }

    var table_requests: std.ArrayList(u32) = .empty;
    for (requested, 0..) |wanted, local| if (wanted) try table_requests.append(arena, @intCast(local));

    // Imports' signatures join the types after every function's.
    const image_imports = try arena.alloc(WasmUnitImage.InputImport, imports.list.items.len);
    for (image_imports, imports.list.items) |*out, import| {
        out.* = import.input;
        if (import.module_type) |module_type| out.type = try types.of(module_type);
    }

    return WasmUnitImage.encode(gpa, .{
        .stack_checks = stack_checks,
        .types = types.list.items,
        .functions = functions,
        .segments = segments,
        .data_exports = data_exports.items,
        .table_requests = table_requests.items,
        .imports = image_imports,
    });
}

fn depth32(depth: u64) error{ImageTooLarge}!u32 {
    return std.math.cast(u32, depth) orelse error.ImageTooLarge;
}

/// Record the table slot a table site takes: a local function's request,
/// or an import's mark that its function needs a slot.
fn markTableSite(site: WasmUnitImage.InputSite, requested: []bool, imports: []Imports.Import) void {
    if (!isTableKind(site.kind)) return;
    switch (site.target_kind) {
        .function => requested[site.target] = true,
        .import => imports[site.target].input.address_taken = true,
        .data, .type, .global => unreachable, // `siteOf` names a function or an import for every table relocation
    }
}

fn isTableKind(kind: WasmUnitImage.SiteKind) bool {
    return switch (kind) {
        .table_index_sleb, .table_index_rel_sleb, .table_index_i32 => true,
        .function_index_leb, .type_index_leb, .memory_addr_leb, .memory_addr_sleb, .memory_addr_rel_sleb, .global_index_leb, .table_number_leb, .stack_room_sleb, .memory_addr_i32 => false,
    };
}

/// Write zero into the field `site` names: the image fixes no index or
/// address of its own.
fn zeroField(bytes: []u8, site: WasmUnitImage.InputSite) void {
    if (site.kind.inData()) {
        @memset(bytes[site.offset..][0..4], 0);
    } else {
        WasmModule.overwritePaddedU32(bytes, site.offset, 0);
    }
}

/// The site a relocation of the unit's module becomes.
fn siteOf(
    entry: WasmLinking.RelocationEntry,
    offset: u32,
    in_data: bool,
    symbols: []const WasmLinking.SymInfo,
    import_count: u32,
    types: *Types,
    imports: *Imports,
    stack_low: ?u32,
) Allocator.Error!WasmUnitImage.InputSite {
    switch (entry) {
        .index => |index| {
            const kind: WasmUnitImage.SiteKind = switch (index.type_id) {
                .function_index_leb => .function_index_leb,
                .type_index_leb => .type_index_leb,
                .table_index_sleb => .table_index_sleb,
                .table_index_rel_sleb => .table_index_rel_sleb,
                .global_index_leb => .global_index_leb,
                .table_number_leb => .table_number_leb,
                .table_index_i32 => .table_index_i32,
                .event_index_leb, .global_index_i32 => base.invariant("wasm unit invariant violated: the codegen emitted a {s} relocation", .{@tagName(index.type_id)}),
            };
            std.debug.assert(kind.inData() == in_data);
            if (kind == .type_index_leb) return .{ .offset = offset, .kind = kind, .target_kind = .type, .target = try types.of(index.symbol_index), .addend = 0 };
            const target = targetOf(symbols, index.symbol_index, import_count, imports);
            return .{ .offset = offset, .kind = kind, .target_kind = target.kind, .target = target.index, .addend = 0 };
        },
        .offset => |reloc| {
            var kind: WasmUnitImage.SiteKind = switch (reloc.type_id) {
                .memory_addr_leb => .memory_addr_leb,
                .memory_addr_sleb => .memory_addr_sleb,
                .memory_addr_rel_sleb => .memory_addr_rel_sleb,
                .memory_addr_i32 => .memory_addr_i32,
                .function_offset_i32, .section_offset_i32 => base.invariant("wasm unit invariant violated: the codegen emitted a {s} relocation", .{@tagName(reloc.type_id)}),
            };
            std.debug.assert(kind.inData() == in_data);
            if (stack_low == reloc.symbol_index) {
                std.debug.assert(kind == .memory_addr_sleb);
                kind = .stack_room_sleb;
            }
            const target = targetOf(symbols, reloc.symbol_index, import_count, imports);
            return .{ .offset = offset, .kind = kind, .target_kind = target.kind, .target = target.index, .addend = reloc.addend + @as(i32, @intCast(target.data_offset)) };
        },
    }
}

const Target = struct { kind: WasmUnitImage.TargetKind, index: u32, data_offset: u32 = 0 };

fn targetOf(symbols: []const WasmLinking.SymInfo, symbol_index: u32, import_count: u32, imports: *const Imports) Target {
    const symbol = symbols[symbol_index];
    if (symbol.isUndefined() or sharedDataDefinition(symbol)) return .{ .kind = .import, .index = imports.indexOfSymbol(symbol_index) };
    return switch (symbol.kind) {
        .function => .{ .kind = .function, .index = symbol.index - import_count },
        .data => .{ .kind = .data, .index = symbol.index, .data_offset = symbol.data_offset },
        .global, .table, .section, .event => base.invariant("wasm unit invariant violated: a relocation names a defined {s} symbol", .{@tagName(symbol.kind)}),
    };
}

/// Whether `symbol` is a constant defined weak under its content name
/// (`contentNamedStaticData`): the unit names it as an import, so a link
/// resolves every unit's references to the one definition it keeps, and
/// exports its own definition weak.
fn sharedDataDefinition(symbol: WasmLinking.SymInfo) bool {
    return !symbol.isUndefined() and symbol.kind == .data and symbol.flags & WasmLinking.SymFlag.BINDING_WEAK != 0;
}

/// The image's signatures, each module signature once, in first-use order.
const Types = struct {
    arena: Allocator,
    module: *const WasmModule,
    list: std.ArrayList(WasmUnitImage.InputType) = .empty,
    by_module_type: std.AutoHashMapUnmanaged(u32, u32) = .empty,
    by_shape: std.StringHashMapUnmanaged(u32) = .empty,

    fn of(self: *Types, module_type: u32) Allocator.Error!u32 {
        if (self.by_module_type.get(module_type)) |index| return index;
        const params = self.module.func_types.items[module_type].params;
        const result = self.module.func_type_results.items[module_type];
        const shape = try self.arena.alloc(u8, params.len + 1 + @intFromBool(result != null));
        for (params, shape[0..params.len]) |param, *byte| byte.* = @backingInt(param);
        // A byte no value type uses separates parameters from results.
        shape[params.len] = 0x40;
        if (result) |valtype| shape[params.len + 1] = @backingInt(valtype);
        const gop = try self.by_shape.getOrPut(self.arena, shape);
        if (!gop.found_existing) {
            gop.value_ptr.* = @intCast(self.list.items.len);
            try self.list.append(self.arena, .{ .params = shape[0..params.len], .results = shape[params.len + 1 ..] });
        }
        try self.by_module_type.put(self.arena, module_type, gop.value_ptr.*);
        return gop.value_ptr.*;
    }
};

/// The image's imports: every undefined symbol a relocation names, one
/// import per kind and name, functions first in the module's import order
/// (builtins, the Boxy runtime, the runtime set, hosted functions, other
/// units' exports), then globals, tables and data symbols.
const Imports = struct {
    arena: Allocator,
    module: *const WasmModule,
    list: std.ArrayList(Import) = .empty,
    by_symbol: std.AutoHashMapUnmanaged(u32, u32) = .empty,

    const Import = struct {
        input: WasmUnitImage.InputImport,
        /// The module signature of a function import, when it has one.
        module_type: ?u32,
        rank: u32,
    };

    fn collect(self: *Imports, code_relocs: []const WasmLinking.RelocationEntry, data_relocs: []const WasmLinking.RelocationEntry) Allocator.Error!void {
        const symbols = self.module.linking.symbol_table.items;
        var referenced = std.AutoArrayHashMapUnmanaged(u32, void).empty;
        for ([_][]const WasmLinking.RelocationEntry{ code_relocs, data_relocs }) |entries| for (entries) |entry| {
            switch (entry) {
                .index => |index| if (index.type_id == .type_index_leb) continue,
                .offset => {},
            }
            const symbol_index = entry.getSymbolIndex();
            if (symbols[symbol_index].isUndefined() or sharedDataDefinition(symbols[symbol_index])) try referenced.put(self.arena, symbol_index, {});
        };
        var candidates: std.ArrayList(struct { symbol: u32, import: Import }) = .empty;
        for (referenced.keys()) |symbol_index| {
            const symbol = symbols[symbol_index];
            const name = symbol.resolveName(self.module.imports.items, self.module.global_imports.items, self.module.table_imports.items) orelse
                base.invariant("wasm unit invariant violated: an imported symbol has no name", .{});
            const import: Import = switch (symbol.kind) {
                .function => blk: {
                    const real = symbol.index < self.module.imports.items.len and std.mem.eql(u8, self.module.imports.items[symbol.index].field_name, name);
                    break :blk .{
                        .input = .{ .module = if (real) self.module.imports.items[symbol.index].module_name else "env", .name = name, .kind = .function },
                        .module_type = if (real) self.module.imports.items[symbol.index].type_idx else null,
                        .rank = if (real) symbol.index else std.math.maxInt(u32),
                    };
                },
                .global => blk: {
                    const global = self.module.global_imports.items[symbol.index];
                    break :blk .{ .input = .{ .module = global.module_name, .name = name, .kind = .global, .valtype = global.val_type, .mutable = global.mutable }, .module_type = null, .rank = symbol.index };
                },
                .table => .{ .input = .{ .module = self.module.table_imports.items[symbol.index].module_name, .name = name, .kind = .table }, .module_type = null, .rank = symbol.index },
                .data => .{ .input = .{ .module = "env", .name = name, .kind = .data }, .module_type = null, .rank = 0 },
                .section, .event => base.invariant("wasm unit invariant violated: a relocation names an undefined {s} symbol", .{@tagName(symbol.kind)}),
            };
            try candidates.append(self.arena, .{ .symbol = symbol_index, .import = import });
        }
        const Candidate = @TypeOf(candidates.items[0]);
        std.mem.sort(Candidate, candidates.items, {}, struct {
            fn lessThan(_: void, a: Candidate, b: Candidate) bool {
                if (a.import.input.kind != b.import.input.kind) return @backingInt(a.import.input.kind) < @backingInt(b.import.input.kind);
                if (a.import.rank != b.import.rank) return a.import.rank < b.import.rank;
                return std.mem.order(u8, a.import.input.name, b.import.input.name) == .lt;
            }
        }.lessThan);
        // One import per kind and name, at the first candidate's place.
        var by_name: std.StringHashMapUnmanaged(u32) = .empty;
        for (candidates.items) |candidate| {
            const key = try std.mem.concat(self.arena, u8, &.{ &.{@backingInt(candidate.import.input.kind)}, candidate.import.input.name });
            const gop = try by_name.getOrPut(self.arena, key);
            if (!gop.found_existing) {
                gop.value_ptr.* = @intCast(self.list.items.len);
                try self.list.append(self.arena, candidate.import);
            } else if (self.list.items[gop.value_ptr.*].module_type == null) {
                self.list.items[gop.value_ptr.*].module_type = candidate.import.module_type;
            }
            try self.by_symbol.put(self.arena, candidate.symbol, gop.value_ptr.*);
        }
    }

    fn indexOfSymbol(self: *const Imports, symbol_index: u32) u32 {
        return self.by_symbol.get(symbol_index) orelse base.invariant("wasm unit invariant violated: undefined symbol {d} is not an import of the unit", .{symbol_index});
    }
};

test "constants with one content name are one weak definition the unit names as an import" {
    const allocator = std.testing.allocator;
    const LIR = lir.LIR;
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    var store = lir.LirStore.init(allocator);
    defer store.deinit();
    var layouts = try layout.Store.init(allocator, .u32);
    defer layouts.deinit();

    // A procedure reading two static-data values whose nodes hold the same
    // string.
    const first = try store.addLocal(.{ .layout_idx = .str });
    const second = try store.addLocal(.{ .layout_idx = .str });
    const ret = try store.addCFStmt(.{ .ret = .{ .value = second } }, .test_fixture);
    const read_second = try store.addCFStmt(.{ .assign_literal = .{ .target = second, .value = .{ .static_data = .{ .id = @fromBackingInt(@intCast(8)) } }, .next = ret } }, .test_fixture);
    const read_first = try store.addCFStmt(.{ .assign_literal = .{ .target = first, .value = .{ .static_data = .{ .id = @fromBackingInt(@intCast(7)) } }, .next = read_second } }, .test_fixture);
    const exported = try store.addProcSpec(.{ .name = store.freshSyntheticSymbol(), .identity = LIR.ProcIdentity.forTest(43), .args = .empty(), .body = read_first, .ret_layout = .str, .exported = true }, .none);

    const contents = "one string two values share";
    const descriptor = try arena.alloc(u8, 12);
    @memset(descriptor, 0);
    std.mem.writeInt(u32, descriptor[4..8], contents.len, .little);
    std.mem.writeInt(u32, descriptor[8..12], contents.len, .little);
    const backing = try arena.alloc(u8, 8 + contents.len);
    @memset(backing[0..8], 0);
    @memcpy(backing[8..], contents);
    const Relocation = @import("../dev/StaticDataExport.zig").StaticDataRelocation;
    const to_first = [_]Relocation{.{ .offset = 0, .target_symbol_name = "roc__d7_1", .target = .{ .data_symbol = @fromBackingInt(@intCast(1)) }, .addend = 8 }};
    const to_second = [_]Relocation{.{ .offset = 0, .target_symbol_name = "roc__d8_1", .target = .{ .data_symbol = @fromBackingInt(@intCast(3)) }, .addend = 8 }};
    const static_data = [_]StaticDataExport{
        .{ .symbol_name = "roc__d7", .value_id = @fromBackingInt(@intCast(7)), .bytes = descriptor, .alignment = 4, .is_global = true, .is_exported = false, .relocations = &to_first },
        .{ .symbol_name = "roc__d7_1", .bytes = backing, .symbol_offset = 8, .alignment = 4, .is_global = true, .is_exported = false },
        .{ .symbol_name = "roc__d8", .value_id = @fromBackingInt(@intCast(8)), .bytes = descriptor, .alignment = 4, .is_global = true, .is_exported = false, .relocations = &to_second },
        .{ .symbol_name = "roc__d8_1", .bytes = backing, .symbol_offset = 8, .alignment = 4, .is_global = true, .is_exported = false },
    };
    const entries = [_]Entry{.{ .symbol_name = "roc__main_for_host", .proc = exported, .arg_layouts = &.{}, .ret_layout = .str }};

    const image = try compileUnitImage(allocator, &store, &layouts, &entries, &static_data, .{ .cpu_level = .default, .stack_checks = false });
    defer allocator.free(image);
    const view = try WasmUnitImage.View.init(image);

    // The two nodes are one weak data export under a content name, and the
    // two slots keep the program's names and their own segments.
    var node_segments: usize = 0;
    var slot_segments: usize = 0;
    for (view.segments()) |segment| {
        if (segment.size == backing.len) node_segments += 1;
        if (segment.size == descriptor.len) slot_segments += 1;
    }
    try std.testing.expectEqual(@as(usize, 1), node_segments);
    try std.testing.expectEqual(@as(usize, 2), slot_segments);
    try std.testing.expectEqual(@as(usize, 1), view.dataExports().len);
    const shared = view.dataExports()[0];
    const shared_name = view.name(shared.name);
    try std.testing.expect(std.mem.startsWith(u8, shared_name, lir.Program.content_data_symbol_prefix));
    try std.testing.expect(shared.flags & WasmUnitImage.definition_weak != 0);
    try std.testing.expectEqual(@as(u32, 8), shared.offset);
    try std.testing.expectEqual(@as(u32, contents.len), shared.size);
    // Both slots name the shared constant as an import, never as their own
    // segment, so a link resolves them to the one definition it keeps.
    var shared_import: ?u32 = null;
    for (view.imports(), 0..) |import, index| {
        if (import.kind == @backingInt(WasmUnitImage.ImportKind.data) and std.mem.eql(u8, view.name(import.name), shared_name)) shared_import = @intCast(index);
    }
    try std.testing.expect(shared_import != null);
    var slot_sites: usize = 0;
    for (view.segments()) |segment| {
        for (view.sites()[segment.first_site..][0..segment.site_count]) |site| {
            try std.testing.expectEqual(@backingInt(WasmUnitImage.TargetKind.import), site.target_kind);
            try std.testing.expectEqual(shared_import.?, site.target);
            try std.testing.expectEqual(@as(i32, 8), site.addend);
            slot_sites += 1;
        }
    }
    try std.testing.expectEqual(@as(usize, 2), slot_sites);
}

test "a unit compiled alone imports what it calls and names its data through sites" {
    const allocator = std.testing.allocator;
    const LIR = lir.LIR;
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    var store = lir.LirStore.init(allocator);
    defer store.deinit();
    var layouts = try layout.Store.init(allocator, .u32);
    defer layouts.deinit();

    // A procedure another unit exports, and one this unit exports that
    // calls it and then reads a string from the unit's static data.
    const linked_identity = LIR.ProcIdentity.forTest(41);
    const exported_identity = LIR.ProcIdentity.forTest(42);
    const linked = try store.addProcSpec(.{ .name = store.freshSyntheticSymbol(), .identity = linked_identity, .args = .empty(), .ret_layout = .u64, .external = true, .linked = true }, .none);
    const called = try store.addLocal(.{ .layout_idx = .u64 });
    const text = try store.addLocal(.{ .layout_idx = .str });
    const ret = try store.addCFStmt(.{ .ret = .{ .value = text } }, .test_fixture);
    const read = try store.addCFStmt(.{ .assign_literal = .{ .target = text, .value = .{ .static_data = .{ .id = @fromBackingInt(@intCast(7)) } }, .next = ret } }, .test_fixture);
    const call = try store.addCFStmt(.{ .assign_call = .{ .target = called, .proc = linked, .args = .empty(), .next = read } }, .test_fixture);
    const exported = try store.addProcSpec(.{ .name = store.freshSyntheticSymbol(), .identity = exported_identity, .args = .empty(), .body = call, .ret_layout = .str, .exported = true }, .none);

    const contents = "a string that lives in static data";
    const descriptor = try arena.alloc(u8, 12);
    @memset(descriptor, 0);
    std.mem.writeInt(u32, descriptor[4..8], contents.len, .little);
    std.mem.writeInt(u32, descriptor[8..12], contents.len, .little);
    const backing = try arena.alloc(u8, 8 + contents.len);
    @memset(backing[0..8], 0);
    @memcpy(backing[8..], contents);
    const relocations = [_]@import("../dev/StaticDataExport.zig").StaticDataRelocation{.{
        .offset = 0,
        .target_symbol_name = "roc__d7_1",
        .target = .{ .data_symbol = @fromBackingInt(@intCast(1)) },
        .addend = 8,
    }};
    const static_data = [_]StaticDataExport{
        .{ .symbol_name = "roc__d7", .value_id = @fromBackingInt(@intCast(7)), .bytes = descriptor, .alignment = 4, .is_global = true, .is_exported = false, .relocations = &relocations },
        .{ .symbol_name = "roc__d7_1", .bytes = backing, .symbol_offset = 8, .alignment = 4, .is_global = true, .is_exported = false },
    };
    const entries = [_]Entry{.{ .symbol_name = "roc__main_for_host", .proc = exported, .arg_layouts = &.{}, .ret_layout = .str }};

    const image = try compileUnitImage(allocator, &store, &layouts, &entries, &static_data, .{ .cpu_level = .default, .stack_checks = false });
    defer allocator.free(image);
    const view = try WasmUnitImage.View.init(image);

    // The callee is an import with the signature the caller uses; the
    // builtins the code never calls are not.
    const linked_name = try linked_identity.symbolName(arena);
    var linked_import: ?u32 = null;
    for (view.imports(), 0..) |import, index| {
        if (std.mem.eql(u8, view.name(import.name), linked_name)) linked_import = @intCast(index);
        try std.testing.expect(import.kind != @backingInt(WasmUnitImage.ImportKind.function) or import.type != WasmUnitImage.no_type);
    }
    try std.testing.expect(linked_import != null);
    try std.testing.expect(view.imports().len < 32);

    // Both the procedure and its entry wrapper are exported.
    const exported_index = view.findExport(try exported_identity.symbolName(arena)) orelse return error.TestUnexpectedResult;
    try std.testing.expect(view.findExport("roc__main_for_host") != null);

    // The procedure calls the import and addresses its data through
    // `__memory_base`, by sites whose fields hold zero.
    var calls_import = false;
    var addresses_data = false;
    var reads_memory_base = false;
    const function = view.functions()[exported_index];
    for (view.functionSites(function)) |site| {
        const field = view.body(function)[site.offset..][0..5];
        try std.testing.expectEqualSlices(u8, &.{ 0x80, 0x80, 0x80, 0x80, 0x00 }, field);
        switch (@as(WasmUnitImage.SiteKind, @fromBackingInt(@intCast(site.kind)))) {
            .function_index_leb => if (site.target_kind == @backingInt(WasmUnitImage.TargetKind.import) and site.target == linked_import.?) {
                calls_import = true;
            },
            .memory_addr_rel_sleb => if (site.target_kind == @backingInt(WasmUnitImage.TargetKind.data)) {
                addresses_data = true;
            },
            .global_index_leb => if (std.mem.eql(u8, view.name(view.imports()[site.target].name), "__memory_base")) {
                reads_memory_base = true;
            },
            .type_index_leb, .table_index_sleb, .table_index_rel_sleb, .memory_addr_leb, .memory_addr_sleb, .table_number_leb, .stack_room_sleb, .memory_addr_i32, .table_index_i32 => {},
        }
    }
    try std.testing.expect(calls_import and addresses_data and reads_memory_base);

    // The descriptor's pointer to its backing is a data site in its
    // segment, naming the backing's content name as an import: the backing
    // is a constant the program named for itself, so it is defined weak
    // under that name for every unit carrying it to share.
    try std.testing.expectEqual(@as(usize, 1), view.dataExports().len);
    const backing_export = view.dataExports()[0];
    try std.testing.expect(std.mem.startsWith(u8, view.name(backing_export.name), lir.Program.content_data_symbol_prefix));
    try std.testing.expect(backing_export.flags & WasmUnitImage.definition_weak != 0);
    var data_sites: usize = 0;
    for (view.segments()) |segment| {
        for (view.segmentSites(segment)) |site| {
            try std.testing.expectEqual(@backingInt(WasmUnitImage.SiteKind.memory_addr_i32), site.kind);
            try std.testing.expectEqual(@backingInt(WasmUnitImage.TargetKind.import), site.target_kind);
            try std.testing.expectEqualStrings(view.name(backing_export.name), view.name(view.imports()[site.target].name));
            // The addend is relative to the symbol, which sits 8 bytes
            // into its segment.
            try std.testing.expectEqual(@as(i32, 8), site.addend);
            data_sites += 1;
        }
    }
    try std.testing.expectEqual(@as(usize, 1), data_sites);

    // Compiling the unit again writes the same image.
    const again = try compileUnitImage(allocator, &store, &layouts, &entries, &static_data, .{ .cpu_level = .default, .stack_checks = false });
    defer allocator.free(again);
    try std.testing.expectEqualSlices(u8, image, again);
}
